local Rc=(getgenv and getgenv()) or _ENV or _G
local ny={} for i=97,122 do ny[#ny+1]=string.char(i) end
local Dq={12,15,1,4,19,20,18,9,14,7}
local NA="" for i=1,#Dq do NA=NA..ny[Dq[i]] end
local nq=Rc and Rc[NA]
local JU=type(nq)=="function"
if JU then
local rq={8,15,15,11,6,21,14,3,20,9,15,14}
local pI="" for i=1,#rq do pI=pI..ny[rq[i]] end
local tc={18,5,19,20,15,18,5,6,21,14,3,20,9,15,14}
local PC="" for i=1,#tc do PC=PC..ny[tc[i]] end
local Zc=Rc[pI]
local TS=Rc[PC]
local Bk=false
if type(Zc)=="function" and type(TS)=="function" then
local RA=function() return 5 end
local vi=pcall(Zc,RA,function() return -777 end)
if vi and RA()==-777 then
local Ro=pcall(TS,RA)
Bk=(Ro and RA()==5)
end
if not Bk then pcall(TS,RA) end
if not Bk and type(Rc.math)=="table" and type(Rc.math.abs)=="function" then
local ra=Rc.math.abs
if ra(5)==5 then
local fO,zi=pcall(Zc,ra,function() return -777 end)
if fO and ra(5)==-777 then
local dQ=pcall(TS,ra)
Bk=(dQ and ra(5)==5)
if not Bk then pcall(TS,ra) Rc.math.abs=(type(zi)=="function" and zi) or function(v) if v<0 then return -v end return v end end
end
end
end
if Bk then
local pE={nq,Zc,TS}
local TO=Rc.string
if type(TO)=="table" then
pE[#pE+1]=TO.char pE[#pE+1]=TO.byte pE[#pE+1]=TO.sub pE[#pE+1]=TO.rep pE[#pE+1]=TO.len
end
if type(Rc.table)=="table" and Rc.table.concat then pE[#pE+1]=Rc.table.concat end
if Rc.pcall then pE[#pE+1]=Rc.pcall end
if type(Rc.math)=="table" and Rc.math.floor then pE[#pE+1]=Rc.math.floor end
for VE=1,#pE do local zt=pE[VE] if type(zt)=="function" then pcall(TS,zt) end end
end
end
end
if not JU then return nil end

